<script lang="ts">
 import Amount from '$lib/components/TransactionAmount.svelte';
 import Badge from '$lib/components/FinancialBadge.svelte';
 import {transactionPresentation} from '$lib/financialPresentation';
 import type {PageData} from './$types';import SplitDialog from '$lib/components/SplitDialog.svelte';import Title from '$lib/components/Title.svelte';import {formatMoney,formatDate} from '$lib/utils';import AddTransactionDialog from '$lib/components/AddTransactionDialog.svelte';
 let {data}:{data:PageData}=$props();let editing=$state(false);let splitting=$state(false);const t=$derived(data.transaction);
 const meaning=$derived(transactionPresentation(t,data.categories).label);
</script>
<Title title={t.merchant||'Transaction'}/><div class="product-page"><a class="product-breadcrumb" href={`/accounts/${t.account_id}?month=${t.date.slice(0,7)}`}>← {t.account_name}</a><header class="product-heading"><div><h1>{t.merchant||'Transaction'}</h1><p>{formatDate(t.date)} · {meaning}</p></div><div class="product-toolbar">{#if t.splits?.length}<button class="product-button" onclick={()=>splitting=true}>Edit splits</button>{/if}<button class="product-button primary" onclick={()=>editing=true}>Edit transaction</button></div></header>
<section class="product-panel"><div class="product-panel-body"><Amount transaction={t} categories={data.categories}/><span class="metric-context">{t.pending?'Pending — not included in posted totals':'Posted'}</span></div><dl class="product-definition"><dt>Account</dt><dd><a class="product-link" href={`/accounts/${t.account_id}?month=${t.date.slice(0,7)}`}>{t.account_name}</a></dd><dt>Category</dt><dd>{#if t.splits?.length}<button class="product-link" onclick={()=>splitting=true}>Split across {t.splits.length} categories</button>{:else if t.category_id}<a class="product-link" href={`/categories/${t.category_id}?month=${t.date.slice(0,7)}`}>{t.category_name}</a>{:else}<button class="product-link" onclick={()=>editing=true}>Choose a category</button>{/if}</dd><dt>Tags</dt><dd>{t.tags?.join(', ')||'No tags'}</dd><dt>Notes</dt><dd>{t.notes||'No notes'}</dd></dl>
{#if t.splits?.length}<header class="product-panel-header"><h2>Split across categories</h2></header><ul class="product-list">{#each t.splits as s}<li><a class="product-row" href={`/categories/${s.category_id}?month=${t.date.slice(0,7)}`}><span>{s.category_name}</span>{#if meaning==='Review split'}<Badge value={formatMoney(t.amount_cents<0?-s.amount_cents:s.amount_cents)} label="Review allocation" tone="attention"/>{:else}<Amount transaction={{...t,amount_cents:t.amount_cents<0?-s.amount_cents:s.amount_cents,category_id:s.category_id,splits:[]}} categories={data.categories}/>{/if}</a></li>{/each}</ul>{/if}
<details class="product-details"><summary>How this affects your finances</summary><p>{t.pending?'Pending activity is excluded from posted income and spending until it posts.':meaning==='Review split'?'These allocations need review and are excluded from income and spending totals until corrected.':t.splits?.length?'Each allocation follows its own category. Transfer portions are not income or spending; refunds and reversals adjust their original categories.':t.category_type==='transfer'?'This moves money between accounts or pays a card. It is visible in account activity but is not counted again as income or spending.':t.category_type==='income'?'This is included in income. A reversal reduces income rather than adding spending.':t.category_type==='expense'?'This is included in spending. Money returned to this category reduces spending rather than adding income.':'Choose a category before including this transaction in income or spending totals.'}</p>{#if t.splits?.length}<p>To change the total or main category, first clear and re-enter the allocations using Edit splits. Changing a payee, note or date keeps them intact.</p>{/if}<p>Source: {t.provider||'Recorded transaction'}. Editing changes this record, not your bank’s reported balance.</p></details></section></div>
{#if editing}<AddTransactionDialog bind:open={editing} editing={t} accounts={data.accounts} categories={data.categories} tags={data.tags} action="/transactions?/save"/>{/if}
